"use client";

import React, { useState } from 'react';
import { ArrowRightIcon, BanknotesIcon, CalendarIcon, UserIcon, PhoneIcon, MapPinIcon } from '@heroicons/react/24/outline';
import Link from 'next/link';
import CustomerCard from '../ui/customers/CustomerCard';

const LoanApplication = ({ onClose }: { onClose: () => void }) => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [district, setDistrict] = useState('');
  const [amount, setAmount] = useState('');
  const [term, setTerm] = useState('');

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    console.log('Loan Application:', { name, phone, district, amount, term });
    onClose(); // Close the form after submission
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gradient-to-r from-blue-50 to-blue-100 p-8">
      <h1 className="text-4xl font-extrabold text-gray-900 mb-8">Apply for a Loan</h1>
      <form onSubmit={handleSubmit} className="bg-white shadow-lg rounded-lg p-8 w-full max-w-lg border border-gray-200">
        <div className="mb-6">
          <label htmlFor="name" className="flex items-center text-sm font-medium text-gray-700 mb-2">
            <UserIcon className="h-5 w-5 mr-2 text-blue-500" />
            Name
          </label>
          <input
            type="text"
            id="name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-4 text-lg focus:outline-none focus:ring-2 focus:ring-blue-500 transition duration-200"
            required
          />
        </div>
        <div className="mb-6">
          <label htmlFor="phone" className="flex items-center text-sm font-medium text-gray-700 mb-2">
            <PhoneIcon className="h-5 w-5 mr-2 text-blue-500" />
            Phone Number
          </label>
          <input
            type="tel"
            id="phone"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-4 text-lg focus:outline-none focus:ring-2 focus:ring-blue-500 transition duration-200"
            required
          />
        </div>
        <div className="mb-6">
          <label htmlFor="district" className="flex items-center text-sm font-medium text-gray-700 mb-2">
            <MapPinIcon className="h-5 w-5 mr-2 text-blue-500" />
            District
          </label>
          <input
            type="text"
            id="district"
            value={district}
            onChange={(e) => setDistrict(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-4 text-lg focus:outline-none focus:ring-2 focus:ring-blue-500 transition duration-200"
            required
          />
        </div>
        <div className="mb-6">
          <label htmlFor="amount" className="flex items-center text-sm font-medium text-gray-700 mb-2">
            <BanknotesIcon className="h-5 w-5 mr-2 text-blue-500" />
            Loan Amount
          </label>
          <input
            type="number"
            id="amount"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-4 text-lg focus:outline-none focus:ring-2 focus:ring-blue-500 transition duration-200"
            required
          />
        </div>
        <div className="mb-6">
          <label htmlFor="term" className="flex items-center text-sm font-medium text-gray-700 mb-2">
            <CalendarIcon className="h-5 w-5 mr-2 text-blue-500" />
            Loan Term (months)
          </label>
          <input
            type="number"
            id="term"
            value={term}
            onChange={(e) => setTerm(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-4 text-lg focus:outline-none focus:ring-2 focus:ring-blue-500 transition duration-200"
            required
          />
        </div>
        <button
          type="submit"
          className="w-full py-3 mt-4 rounded-md bg-gradient-to-r from-blue-500 to-indigo-600 text-white text-lg font-bold hover:bg-gradient-to-l hover:from-blue-600 hover:to-indigo-500 transition duration-300"
        >
          Submit Application <ArrowRightIcon className="w-5 ml-2 inline" />
        </button>
      </form>
      <Link href="/dashboard" className="mt-4 text-blue-500 hover:underline text-sm" onClick={onClose}>
        Back to Dashboard
      </Link>
    </div>
  );
};

const DashboardPage = () => {
  const [showLoanForm, setShowLoanForm] = useState(false);

  const customers = [
    {
      name: 'Amy Burns',
      photo: '/customers/amy-burns.png',
      loanTaken: '2023-01-15',
      loanRepayment: '2023-07-15'
    },
    {
      name: 'Balazs Orban',
      photo: '/customers/balazs-orban.png',
      loanTaken: '2023-02-20',
      loanRepayment: '2023-08-20'
    },
    {
      name: 'Delba de Oliveira',
      photo: '/customers/delba-de-oliveira.png',
      loanTaken: '2023-03-10',
      loanRepayment: '2023-09-10'
    }
  ];

  return (
    <div className="p-6 flex flex-col justify-between min-h-screen bg-gradient-to-r from-blue-50 to-blue-100">
      <h1 className="text-4xl font-extrabold text-gray-900 mb-6">Dashboard</h1>

      {/* Existing Loan Application Guidelines Section */}
      {/* ... existing guidelines code ... */}

      <div className="mt-auto">
        <button 
          onClick={() => setShowLoanForm(true)} 
          className="mt-4 w-full rounded-lg bg-gradient-to-r from-green-500 to-teal-500 px-6 py-3 text-white text-lg font-bold hover:bg-gradient-to-l hover:from-green-600 hover:to-teal-400 transition duration-300"
        >
          Apply Loan
        </button>
      </div>

      {/* Display Loan Form */}
      {showLoanForm && <LoanApplication onClose={() => setShowLoanForm(false)} />}

      {/* Customer List Section */}
      <div className="customer-list mt-6">
        {customers.map((customer, index) => (
          <CustomerCard
            key={index}
            name={customer.name}
            photo={customer.photo}
            loanTaken={customer.loanTaken}
            loanRepayment={customer.loanRepayment}
          />
        ))}
      </div>
    </div>
  );
};
